import requests

def download_file_streaming(url, output_filename, chunk_size=8192):
    """Download a file using streaming to avoid loading entire body into memory."""
    response = requests.get(url, stream=True)
    response.raise_for_status()

    with open(output_filename, 'wb') as f:
        for chunk in response.iter_content(chunk_size=chunk_size):
            if chunk:
                f.write(chunk)

if __name__ == "__main__":
    download_file_streaming("https://example.com/big.bin", "big.bin")
